from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    if h % 2 == 1 and len(set(grid[h // 2])) == 1:
        k = h // 2
        a, b = grid[:k], grid[k + 1:]
    elif w % 2 == 1 and len({grid[r][w // 2] for r in range(h)}) == 1:
        k = w // 2
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]
    else:
        raise ValueError("no central separator")
    ca = {v for row in a for v in row}
    cb = {v for row in b for v in row}
    shared = ca & cb
    color = next(iter(shared))
    return [[color for _ in row] for row in a]
